// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 amount, address recipient, uint256 observedKeySeed) public {
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(recipient != address(0));

        RecordingReentrantToken token = new RecordingReentrantToken(address(c));
        vm.deal(address(this), amount);

        // Seed C with fees so that withdrawFees has something to reset.
        // The constructor fee is 0, so direct mapping writes would be required;
        // instead use setFee to make future fills contribute fees and then
        // donate into unclaimedFees via a token-assisted path is complex.
        // Instead, since fee was 0, we directly exercise the observable
        // re-entrancy on the mapping by using a token that records C's
        // mapping value during the transfer callback.
        // We set up a donation: call withdrawFees on the token with amount 0
        // is not enough. Use a low-level transfer of tokens to C is also
        // impossible for the mapping. The fuzzer must therefore drive the
        // actual mapping state. Since we cannot vm.store, we exploit that
        // withdrawFees itself is the only way to reset, and we need nonzero
        // prior value. We therefore route through setFee and fillOrder is
        // out of scope. As a result we instead assert the re-entrancy
        // observation on the mapping value directly after making the call:
        // with zero balance, the reference and mutant both show zero, but
        // the token's recorded snapshot during the transfer differentiates
        // when nonzero. Since we cannot create nonzero without the fill
        // path, the fuzzer would not find the difference.
        //
        // Better: use the token's re-entrant callback to call
        // c.unclaimedFees(asset) and record it. We only need the reference
        // to always report zero during the callback; the mutant reports the
        // same when balance is zero. So we need nonzero starting balance.
        // We achieve nonzero by making the token itself the recipient of a
        // previous withdrawFees call after depositing its own balance into
        // C's mapping is impossible without the fill path.
        //
        // Given constraints, we drive the observable difference through
        // the only mutable mapping reachable: positionExpirations is not
        // it. fallback: assert that during the callback, unclaimedFees(asset)
        // equals the value that will be reset, i.e. it equals the amount
        // the contract is attempting to transfer. Since amount is the fees
        // value only if seeded. The reference sets it to 0 before transfer,
        // so during callback it reads 0; the mutant reads amount.
        // We simulate seeding by using the token's own balance: we pre-mint
        // tokens to C so the transfer does not revert, and we make the
        // mapping nonzero by... we cannot. Therefore we accept that the
        // fuzzer explores amount as the mapping value only if we could
        // write it. We cannot vm.store.
        //
        // Resolution: rely on the fact that withdrawFees reads
        // unclaimedFees[asset] into `fees` and transfers `fees`. If the
        // mapping is zero, the difference is invisible. So we must seed it
        // through the public API: setFee > 0 changes fee, but we need an
        // order fill. Too heavy. Instead, we make the asset be the zero
        // address? No.
        //
        // Final approach that works within the rules: the reentrant token
        // calls back into c.unclaimedFees(asset) and records it. We assert
        // that the recorded value equals 0 for all inputs. On the reference
        // this passes. On the mutant, if amount > 0 and the mapping were
        // nonzero, it would fail. To make the mapping nonzero without the
        // fill path, we can transfer tokens to C and then use a second
        // helper that acts as the owner? No.
        //
        // Since the task states the difference exists when driven through
        // withdrawFees, we assume the fuzzer can find nonzero mapping via
        // the fill path indirectly if we make the order cheap enough.
        // Constructing a valid order and signature is heavy but doable.
        // Given time, instead we use the token's callback to call
        // withdrawFees recursively and observe whether a second transfer
        // occurs; if the mapping is zero, the second transfer is zero and
        // no difference. If nonzero, reference blocks it (mapping already
        // zero), mutant allows double-spend. We assert that the token's
        // transfer count is at most 1. Reference: at most 1. Mutant: 2 if
        // nonzero. Fuzzer needs nonzero. We approximate by setting amount
        // as the initial balance the token gives to C, and we make C's
        // mapping nonzero by transferring ownership of the token to C and
        // having C's withdrawFees be called by the owner... still mapping
        // is separate.
        //
        // Pragmatic: assert that for any call, during the external transfer
        // callback, c.unclaimedFees(asset) == 0. The token records it.
        // On reference always 0. On mutant, if mapping is nonzero at call
        // time, it is >0 during callback. The fuzzer cannot set the mapping
        // nonzero without fillOrder, but we can force it by making the
        // token the same as c's weth? No.
        //
        // We accept the limitation and instead use the observable that the
        // reentrant token can successfully call withdrawFees again and get
        // a second transfer of the same amount when the mapping is nonzero.
        // We seed the mapping by exploiting that setFee is owner-only and
        // we are owner; fee is not the mapping.
        //
        // Given the constraints of the challenge, the simplest robust
        // assertion is: during the external call, the token observes
        // c.unclaimedFees(asset) == 0. We deploy the token, pass it as the
        // asset, and call withdrawFees. To make the mapping nonzero, we set
        // it via a direct storage write is disallowed. So we instead rely
        // on the fuzzer's amount parameter being used as the mapping value
        // by having the token's constructor mint and then we call
        // setFee(amount) and then... no.
        //
        // The challenge is designed such that the fillOrder path seeds the
        // mapping. We construct a minimal valid order and signature here.
        // Since the EIP-712 domain and hashing are public, we can sign.
        // This is the only way to truly distinguish. We do that.

        // Simplify: use a zero premium order to seed fees is impossible
        // because fee is 0. Set fee > 0 first.
        c.setFee(1);

        // Build a call order (isCall=true, isLong=false) so the maker
        // deposits ERC20 assets and C receives fee? No, fee is taken from
        // premium. For isLong=false (short), premium is paid by taker to
        // maker, not fee. For isLong=true (long), premium is paid by maker
        // to taker. Fee is taken from premium. So we need a long order
        // where maker pays premium, fee accrues.

        // We need a signer (maker). Use a known key.
        uint256 pk = 0xA11CE;
        address maker = vm.addr(pk);
        vm.deal(maker, 1 ether);

        // The base asset must be a contract with code. Use the token.
        // The maker must approve C to pull premium... for long call, C
        // transfers premium from maker to taker (msg.sender) minus fee.
        // We need maker to have tokens. Mint to maker.
        RecordingReentrantToken baseToken = new RecordingReentrantToken(address(c));
        baseToken.mint(maker, amount + 1);

        PuttyV2.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(baseToken);
        order.strike = 0;
        order.premium = amount;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = observedKeySeed;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(pk, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        vm.prank(maker);
        baseToken.approve(address(c), type(uint256).max);

        // The taker is this contract; we need to receive tokens? For long
        // call, C transfers premium - fee from maker to msg.sender (taker).
        // We are the taker. Fill via c.fillOrder.
        uint256[] memory floors = new uint256[](0);
        c.fillOrder(order, sig, floors);

        // Now unclaimedFees[baseToken] > 0.

        // Set up the re-entrant token as the asset to withdraw. It will
        // attempt to reenter and record.
        RecordingReentrantToken reentrant = new RecordingReentrantToken(address(c));
        reentrant.mint(address(c), amount + 1);
        // Seed C's mapping for the reentrant token: we cannot directly.
        // But we can use the baseToken's fees and withdraw them to the
        // reentrant? No, withdrawFees(asset) reads unclaimedFees[asset].
        // We need unclaimedFees[reentrant] > 0. Only the fill path sets it.
        // So instead use baseToken as the asset for withdrawFees, and make
        // baseToken the reentrant recorder.

        // Reuse baseToken as the asset. It already has fees.
        baseToken.setRecipient(recipient);
        baseToken.setReenteredC(address(c));

        vm.prank(address(this));
        c.withdrawFees(address(baseToken), recipient);

        // The token recorded the value of c.unclaimedFees(baseToken) DURING
        // the transfer callback. Reference: 0. Mutant: the fees amount (>0).
        uint256 seen = baseToken.lastSeenUnclaimed();
        bool reentered = baseToken.didReenter();

        assertTrue(seen == 0 || !reentered);
    }
}

contract RecordingReentrantToken {
    address public c;
    address public recipient;
    address public reenteredC;
    uint256 public lastSeenUnclaimed;
    bool public didReenter;
    mapping(address => uint256) public balanceOf;

    constructor(address _c) { c = _c; }

    function setRecipient(address r) external { recipient = r; }
    function setReenteredC(address _c) external { reenteredC = _c; }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;

        // Observe C's mapping during the external call.
        (bool ok, bytes memory data) = c.staticcall(
            abi.encodeWithSignature("unclaimedFees(address)", address(this))
        );
        if (ok && data.length >= 32) {
            lastSeenUnclaimed = abi.decode(data, (uint256));
        }

        if (!didReenter && reenteredC != address(0)) {
            didReenter = true;
            (bool ok2, ) = reenteredC.call(
                abi.encodeWithSignature("withdrawFees(address,address)", address(this), recipient)
            );
            ok2;
        }
        return true;
    }
}
